    for (int i = 0; i < strings.size(); i++) {
        for (int j = i + 1; j < strings.size(); j++) {
            String str1 = strings.get(i);
            String str2 = strings.get(j);

            int len = Math.min(str1.length(), str2.length());

            for (int length = len; length > 0; length--) {
                for (int start = 0; start <= len - length; start++) {
                    String sub1 = str1.substring(start, start + length);
                    String sub2 = new StringBuilder(sub1).reverse().toString();

                    if (str2.contains(sub1) || str2.contains(sub2)) {
                        maxLength = Math.max(maxLength, length);
                        break;
                    }
                }
            }
        }
    }

    return maxLength;
}

