public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int numRows = grid.length;
    int numCols = grid[0].length;
    boolean[][] visited = new boolean[numRows][numCols];
    int depositCount = 0;

    for (int row = 0; row < numRows; row++) {
        for (int col = 0; col < numCols; col++) {
            if (grid[row][col] == '@' && !visited[row][col]) {
                depositCount++;
                markDeposit(grid, visited, row, col);
            }
        }
    }

    return depositCount;
}

private static void markDeposit(char[][] grid, boolean[][] visited, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != '@' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;

    markDeposit(grid, visited, row - 1, col); // up
    markDeposit(grid, visited, row + 1, col); // down
    markDeposit(grid, visited, row, col - 1); // left
    markDeposit(grid, visited, row, col + 1); // right
    markDeposit(grid, visited, row - 1, col - 1); // up-left
    markDeposit(grid, visited, row - 1, col + 1); // up-right
    markDeposit(grid, visited, row + 1, col - 1); // down-left
    markDeposit(grid, visited, row + 1, col + 1); // down-right
}

