public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }

    if (x == endX && y == endY) {
        return true;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        int newX = x + path[0];
        int newY = y + path[1];
        if (canTravel(n, newX, newY, endX, endY, paths, visited)) {
            return true;
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    try {
        return (dfs(start[0], start[1], end[0], end[1], paths, visited)) ? "can be travelled" : "cannot be travelled";
    } catch (ArrayIndexOutOfBoundsException | IllegalArgumentException e) {
        return "cannot be travelled";
    }
}

private static boolean dfs(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;

    for (int[] path : paths) {
        int newX = x + path[0];
        int newY = y + path[1];
        if (newX >= 0 && newX < visited.length && newY >= 0 && newY < visited[0].length && !visited[newX][newY]) {
            if (dfs(newX, newY, endX, endY, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

