    boolean[][] visited = new boolean[n][n];
    return canTravelUtil(start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelUtil(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }

    if (x < 0 || y < 0 || x >= visited.length || y >= visited[0].length || visited[x][y]) {
        return false;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        int newX = x + path[0];
        int newY = y + path[1];
        if (canTravelUtil(newX, newY, endX, endY, paths, visited)) {
            return true;
        }
    }

    visited[x][y] = false;
    return false;
}

