private static boolean canTravel(int n, int startX, int startY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (startX == endX && startY == endY) {
        return true;
    }

    visited[startX][startY] = true;

    for (int[] path : paths) {
        if (path.length != 4) continue;

        int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];

        if ((x1 == startX && y1 == startY && !visited[x2][y2]) ||
            (x2 == startX && y2 == startY && !visited[x1][y1])) {

            if (canTravel(n, x2, y2, endX, endY, paths, visited)) {
                return true;
            }
        }
    }

    visited[startX][startY] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], visited, paths, n);

    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int currentX, int currentY, int endX, int endY, boolean[][] visited, int[][] paths, int n) {
    if (currentX == endX && currentY == endY) {
        return true;
    }

    if (currentX < 0 || currentX >= n || currentY < 0 || currentY >= n || visited[currentX][currentY]) {
        return false;
    }

    visited[currentX][currentY] = true;

    for (int[] path : paths) {
        int nextX = currentX + path[0];
        int nextY = currentY + path[1];
        if (dfs(nextX, nextY, endX, endY, visited, paths, n)) {
            return true;
        }
    }

    return false;
}

