        commonLetters += Math.min(letterCount1[i], letterCount2[i]);
    }

    int totalLength = word1.length() + word2.length();

    int gcd = gcd(commonLetters, totalLength);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonLetters / gcd) + "/" + (totalLength / gcd);
}

