public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || s.length() < k) {
        return false;
    }

    Set<String> seen = new HashSet<>();
    int totalPossible = 1 << k; // 2^k

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
        if (seen.size() == totalPossible) {
            return true;
        }
    }

    return seen.size() == totalPossible;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || k > s.length()) {
        return false;
    }

    int totalSubstringsNeeded = 1 << k; // 2^k
    boolean[] found = new boolean[totalSubstringsNeeded];
    int val = 0;
    int mask = totalSubstringsNeeded - 1; // 2^k - 1 to get k bits

    for (int i = 0; i < s.length(); i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1 && !found[val]) {
            found[val] = true;
            totalSubstringsNeeded--;
            if (totalSubstringsNeeded == 0) {
                return true;
            }
        }
    }

    return false;
}

