public int minInsertions(String s) {
    int left = 0, right = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                left++;
                right--;
            }
            right += 2;
        } else {
            right--;
            if (right == -1) {
                left++;
                right = 1;
            }
        }
    }
    return left + right;
}

public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int insertions = 0;
    int openCount = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            openCount++;
        } else if (c == ')') {
            if (openCount > 0) {
                openCount--;
            } else {
                insertions++;
            }
        }
    }

    insertions += openCount * 2;
    return insertions;
}

public int minInsertions(String s) {
    int openNeeded = 0; // To count the number of '(' needed
    int closeNeeded = 0; // To count the number of ')' needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            closeNeeded += 2; // Each '(' needs two ')' to be potentially balanced
            if (closeNeeded % 2 == 1) {
                openNeeded++; // If we need an odd number of ')', we need to add one '('
                closeNeeded--; // Now we need one less ')' as we added a '('
            }
        } else {
            closeNeeded--; // Each ')' closes one needed ')'
            if (closeNeeded == -1) {
                openNeeded++; // If we have more ')' than needed, we need a '('
                closeNeeded = 1; // Now we need one ')'
            }
        }
    }

    return openNeeded + closeNeeded;
}

public int minInsertions(String s) {
    int open = 0; // To count unmatched '('
    int close = 0; // To count required ')'

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close > 0) { // If there are unmatched ')'
                open++; // Add '(' to match previous ')'
                close--; // Match one ')'
            }
            open++; // Increment open for new '('
        } else {
            open--; // Try to match with existing '('
            if (open < 0) { // If no '(' to match
                open = 0; // Reset open count
                close++; // Need one more ')'
            }
        }
    }

    // Total insertions needed is unmatched '(' + required ')'
    return open + close;
}

public int minInsertions(String s) {
    int open = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insertions++;
            }
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ) as it matches the current (
            } else {
                insertions++; // Need to add a ) to match the current (
            }
        }
    }

    insertions += open * 2; // Each unmatched ( needs two )
    return insertions;
}

