public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return maxUniqueSplitHelper(s, new HashSet<>());
}

private int maxUniqueSplitHelper(String s, Set<String> seen) {
    if (s.isEmpty()) {
        return 0;
    }
    int maxUnique = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!seen.contains(prefix)) {
            seen.add(prefix);
            maxUnique = Math.max(maxUnique, 1 + maxUniqueSplitHelper(s.substring(i), seen));
            seen.remove(prefix);
        }
    }
    return maxUnique;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string must not be null or empty");
    }
    return backtrack(s, 0, new HashSet<>());
}

private int backtrack(String s, int start, Set<String> seen) {
    if (start == s.length()) {
        return 0;
    }
    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (!seen.contains(substring)) {
            seen.add(substring);
            maxUnique = Math.max(maxUnique, 1 + backtrack(s, end, seen));
            seen.remove(substring);
        }
    }
    return maxUnique;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        throw new IllegalArgumentException("Input string must not be null or empty");
    }
    return backtrack(s, 0, new HashSet<>());
}

private int backtrack(String s, int start, Set<String> used) {
