public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        findSteppingNumbersHelper(i, i, high, result);
    }
    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(int current, int lastDigit, int high, List<Integer> result) {
    if (current > high) {
        return;
    }
    if (current >= 0) {
        result.add(current);
    }
    if (lastDigit > 0) {
        findSteppingNumbersHelper(current * 10 + (lastDigit - 1), lastDigit - 1, high, result);
    }
    if (lastDigit < 9) {
        findSteppingNumbersHelper(current * 10 + (lastDigit + 1), lastDigit + 1, high, result);
    }
}

