public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.add(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num == 0 || num > high) {
            continue;
        }

        int lastDigit = num % 10;
        int nextNum1 = num * 10 + lastDigit + 1;
        int nextNum2 = num * 10 + lastDigit - 1;

        if (lastDigit < 9 && nextNum1 <= high) {
            queue.add(nextNum1);
        }
        if (lastDigit > 0 && nextNum2 <= high) {
            queue.add(nextNum2);
        }
    }

    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    for (int i = low; i <= Math.min(high, 9); i++) {
        result.add(i);
    }
    for (int i = 1; i <= 9; i++) {
        dfs(result, i, low, high);
    }
    Collections.sort(result);
    return result;
}

private static void dfs(List<Integer> result, int number, int low, int high) {
    if (number > high) {
        return;
    }
    if (number >= low) {
        result.add(number);
    }
    int lastDigit = number % 10;
    if (lastDigit > 0) {
        int next = number * 10 + (lastDigit - 1);
        if (next <= high) {
            dfs(result, next, low, high);
        }
    }
    if (lastDigit < 9) {
        int next = number * 10 + (lastDigit + 1);
        if (next <= high) {
            dfs(result, next, low, high);
        }
    }
}

