private static void backtrack(List<Integer> numbers, List<Integer> tempList, Set<List<Integer>> result) {
    if (numbers.isEmpty()) {
        result.add(new ArrayList<>(tempList));
    } else {
        for (int i = 0; i < numbers.size(); i++) {
            if (i > 0 && numbers.get(i) == numbers.get(i - 1)) continue; // Skip duplicates
            int lastNum = tempList.isEmpty() ? -1 : tempList.get(tempList.size() - 1);
            int currentNum = numbers.get(i);
            if (lastNum == -1 || isPerfectSquare(lastNum + currentNum)) {
                tempList.add(currentNum);
                numbers.remove(i);
                backtrack(numbers, tempList, result);
                numbers.add(i, currentNum);
                tempList.remove(tempList.size() - 1);
            }
        }
    }
}

