public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    boolean isCenter = n % 2 != 0;
    int mid = n / 2;
    char[] current = new char[n];
    if (isCenter) {
        current[mid] = '0';
        buildNumbers(pairs, result, current, mid - 1, mid + 1);
        current[mid] = '1';
        buildNumbers(pairs, result, current, mid - 1, mid + 1);
        current[mid] = '8';
        buildNumbers(pairs, result, current, mid - 1, mid + 1);
    } else {
        buildNumbers(pairs, result, current, mid - 1, mid);
    }
    return result;
}

private static void buildNumbers(char[][] pairs, List<String> result, char[] current, int left, int right) {
    if (left < 0) {
        result.add(new String(current));
        return;
    }
    for (char[] pair : pairs) {
        if (left == 0 && pair[0] == '0') {
            continue; // Skip leading zeros
        }
        current[left] = pair[0];
        current[right] = pair[1];
        buildNumbers(pairs, result, current, left - 1, right + 1);
    }
}

