    }
    if (currentLength == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    List<String> subResult = generateCenterSymmetric(currentLength - 2, targetLength, pairs);
    for (String s : subResult) {
        for (int i = (currentLength == targetLength ? 1 : 0); i < pairs.length; i++) {
            result.add(pairs[i].charAt(0) + s + pairs[i].charAt(1));
        }
    }
    return result;
}

