public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    char[] number = new char[n];
    generateCenterSymmetricNumbers(number, 0, n - 1, pairs, result);
    return result;
}

private static void generateCenterSymmetricNumbers(char[] number, int left, int right, char[][] pairs, List<String> result) {
    if (left > right) {
        result.add(new String(number));
        return;
    }
    for (char[] pair : pairs) {
        number[left] = pair[0];
        number[right] = pair[1];
        if (number.length > 1 && number[0] == '0') {
            continue;
        }
        if (left == right && pair[0] != pair[1]) {
            continue;
        }
        generateCenterSymmetricNumbers(number, left + 1, right - 1, pairs, result);
    }
}

